START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20261001205445_AddFgsJobTypeAccounting') THEN
    CREATE TABLE setup."FgsJobTypeAccounting" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "JobTypeId" bigint NOT NULL,
        "ArAccountId" bigint,
        "DiscountAccountId" bigint,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        CONSTRAINT "PK_FgsJobTypeAccounting" PRIMARY KEY ("Id"),
        CONSTRAINT "UQ_FgsJobTypeAccounting_TenantId_CompanyId_JobTypeId" UNIQUE ("TenantId", "CompanyId", "JobTypeId"),
        CONSTRAINT "FK_FgsJobTypeAccounting_FgsJobType" FOREIGN KEY ("JobTypeId") REFERENCES setup."FgsJobType" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_FgsJobTypeAccounting_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES setup."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT
    );
    COMMENT ON TABLE setup."FgsJobTypeAccounting" IS 'Stores optional accounting configuration that applies at the job type level independently of billing category, including Accounts Receivable and Discount GL account mappings.';
    COMMENT ON COLUMN setup."FgsJobTypeAccounting"."Id" IS 'Primary key identity of the job type accounting record.';
    COMMENT ON COLUMN setup."FgsJobTypeAccounting"."TenantId" IS 'Tenant identifier owning this job type accounting configuration.';
    COMMENT ON COLUMN setup."FgsJobTypeAccounting"."CompanyId" IS 'Company identifier within the tenant owning this job type accounting configuration.';
    COMMENT ON COLUMN setup."FgsJobTypeAccounting"."JobTypeId" IS 'Identifier of the job type to which the accounting configuration applies.';
    COMMENT ON COLUMN setup."FgsJobTypeAccounting"."ArAccountId" IS 'Optional GL account used to record accounts receivable for transactions associated with the job type. This account is independent of billing category.';
    COMMENT ON COLUMN setup."FgsJobTypeAccounting"."DiscountAccountId" IS 'Optional GL account used to record discounts associated with the job type. This account is independent of billing category.';
    COMMENT ON COLUMN setup."FgsJobTypeAccounting"."CreatedOn" IS 'Date and time the job type accounting configuration was created.';
    COMMENT ON COLUMN setup."FgsJobTypeAccounting"."CreatedBy" IS 'User identifier that created the job type accounting configuration.';
    COMMENT ON COLUMN setup."FgsJobTypeAccounting"."UpdatedOn" IS 'Date and time the job type accounting configuration was last updated.';
    COMMENT ON COLUMN setup."FgsJobTypeAccounting"."UpdatedBy" IS 'User identifier that last updated the job type accounting configuration.';
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM setup."__EFMigrationsHistory" WHERE "MigrationId" = '20261001205445_AddFgsJobTypeAccounting') THEN
    CREATE TABLE setup."FgsJobTypeBillingCategoryAccounting" (
        "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
        "TenantId" bigint NOT NULL,
        "CompanyId" bigint NOT NULL,
        "JobTypeId" bigint NOT NULL,
        "BillingCategoryId" bigint NOT NULL,
        "RevenueAccountId" bigint,
        "CogsAccountId" bigint,
        "InventoryOffsetAccountId" bigint,
        "CreatedOn" timestamptz NOT NULL DEFAULT (now()),
        "CreatedBy" character varying(100),
        "UpdatedOn" timestamptz,
        "UpdatedBy" character varying(100),
        CONSTRAINT "PK_FgsJobTypeBillingCategoryAccounting" PRIMARY KEY ("Id"),
        CONSTRAINT "UQ_FgsJobTypeBillingCategoryAccounting_TenantId_CompanyId_JobTypeId_BillingCategoryId" UNIQUE ("TenantId", "CompanyId", "JobTypeId", "BillingCategoryId"),
        CONSTRAINT "FK_FgsJobTypeBillingCategoryAccounting_FgsBillingCategory" FOREIGN KEY ("BillingCategoryId") REFERENCES setup."FgsBillingCategory" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_FgsJobTypeBillingCategoryAccounting_FgsJobType" FOREIGN KEY ("JobTypeId") REFERENCES setup."FgsJobType" ("Id") ON DELETE CASCADE,
        CONSTRAINT "FK_FgsJobTypeBillingCategoryAccounting_FgsTenantCompanyCache_TenantId_CompanyId" FOREIGN KEY ("TenantId", "CompanyId") REFERENCES setup."FgsTenantCompanyCache" ("TenantId", "CompanyId") ON DELETE RESTRICT
    );
    COMMENT ON TABLE setup."FgsJobTypeBillingCategoryAccounting" IS 'Stores optional accounting overrides for a specific Job Type and Billing Category combination. These mappings allow a Job Type to override the default Revenue, COGS, and Inventory Offset GL accounts defined for the Billing Category.';
    COMMENT ON COLUMN setup."FgsJobTypeBillingCategoryAccounting"."Id" IS 'Primary key identity of the Job Type and Billing Category accounting configuration record.';
    COMMENT ON COLUMN setup."FgsJobTypeBillingCategoryAccounting"."TenantId" IS 'Tenant identifier owning this Job Type and Billing Category accounting configuration.';
    COMMENT ON COLUMN setup."FgsJobTypeBillingCategoryAccounting"."CompanyId" IS 'Company identifier within the tenant owning this Job Type and Billing Category accounting configuration.';
    COMMENT ON COLUMN setup."FgsJobTypeBillingCategoryAccounting"."JobTypeId" IS 'Identifier of the Job Type to which the accounting override applies.';
    COMMENT ON COLUMN setup."FgsJobTypeBillingCategoryAccounting"."BillingCategoryId" IS 'Identifier of the Billing Category for which the Job Type accounting override is defined.';
    COMMENT ON COLUMN setup."FgsJobTypeBillingCategoryAccounting"."RevenueAccountId" IS 'Optional GL account used for revenue generated by the Job Type when the specified Billing Category applies. If not configured, the Billing Category default Revenue account can be used.';
    COMMENT ON COLUMN setup."FgsJobTypeBillingCategoryAccounting"."CogsAccountId" IS 'Optional GL account used for cost of goods sold when the specified Billing Category applies to the Job Type. If not configured, the Billing Category default COGS account can be used.';
    COMMENT ON COLUMN setup."FgsJobTypeBillingCategoryAccounting"."InventoryOffsetAccountId" IS 'Optional GL account used as the inventory offset when the specified Billing Category is an Inventory billing category. If not configured, the Billing Category default Inventory Offset account can be used.';
    COMMENT ON COLUMN setup."FgsJobTypeBillingCategoryAccounting"."CreatedOn" IS 'Date and time the Job Type and Billing Category accounting configuration was created.';
    COMMENT ON COLUMN setup."FgsJobTypeBillingCategoryAccounting"."CreatedBy" IS 'User identifier that created the Job Type and Billing Category accounting configuration.';
    COMMENT ON COLUMN setup."FgsJobTypeBillingCategoryAccounting"."UpdatedOn" IS 'Date and time the Job Type and Billing Category accounting configuration was last updated.';
    COMMENT ON COLUMN setup."FgsJobTypeBillingCategoryAccounting"."UpdatedBy" IS 'User identifier that last updated the Job Type and Billing Category accounting configuration.';
    END IF;
END $EF$;

